373	                && self.ref_counts@.index(i).constant() == (self.inst, i)
374	        }
375	
376	        invariant on exc_locked with (inst) is (b: bool, g: DistRwLock::exc_locked<T>) {
377	            g.instance_id() == inst@.id()
